style.css:
@-moz-document domain("websim.com"), domain("www.websim.com") {
:root {
    --bg: #0b0f14;               /* page background */
    --bg-2: rgba(255,255,255,0.03);
    --surface: rgba(255,255,255,0.04);
    --glass: rgba(255,255,255,0.06);
    --muted: rgba(255,255,255,0.65);
    --text: #e6eef6;
    --accent: #63f0ff;           /* neon cyan accent */
    --accent-2: #6ef28e;         /* secondary accent (green) */
    --danger: #ff6b6b;
    --radius: 12px;
    --shadow-1: 0 6px 18px rgba(2,6,23,0.6);
    --glass-border: rgba(255,255,255,0.06);
    --glass-blur: 8px;
    --transition: 200ms cubic-bezier(.2,.9,.2,1);
    --max-width: 1200px;
    --mono: "SFMono-Regular", Menlo, Monaco, "Roboto Mono", monospace;
    --ui-font: Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue";
  }

  /* Global page */
  html, body {
    background: linear-gradient(180deg, var(--bg) 0%, #071018 100%) fixed;
    color: var(--text);
    font-family: var(--ui-font);
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    line-height: 1.45;
    min-height: 100%;
  }

  /* Constrain layout */
  .container, #main, main, .site-wrapper {
    max-width: var(--max-width);
    margin: 24px auto;
    padding: 18px;
    box-sizing: border-box;
  }

  /* Header / Nav */
  header, .topbar, .navbar {
    background: linear-gradient(180deg, rgba(255,255,255,0.02), transparent);
    backdrop-filter: blur(var(--glass-blur));
    border: 1px solid var(--glass-border);
    border-radius: 14px;
    padding: 10px 14px;
    box-shadow: var(--shadow-1);
    display: flex;
    gap: 12px;
    align-items: center;
  }
  header .logo {
    display: flex;
    align-items: center;
    gap: 10px;
  }
  header .logo img { height: 36px; width: auto; border-radius: 8px; }
  header .brand {
    font-weight: 700;
    font-size: 1.1rem;
    letter-spacing: 0.6px;
    color: var(--text);
  }
  nav a, .nav-link {
    color: var(--muted);
    padding: 8px 10px;
    border-radius: 10px;
    text-decoration: none;
    transition: color var(--transition), background var(--transition), transform var(--transition);
  }
  nav a:hover, .nav-link:hover {
    color: var(--text);
    background: linear-gradient(90deg, rgba(99,240,255,0.06), rgba(110,242,142,0.03));
    transform: translateY(-2px);
  }

  /* Search bar */
  .search, input[type="search"], input[type="text"].search {
    background: linear-gradient(180deg, rgba(255,255,255,0.02), rgba(255,255,255,0.01));
    border: 1px solid var(--glass-border);
    color: var(--text);
    padding: 10px 12px;
    border-radius: 12px;
    width: 100%;
    max-width: 520px;
    transition: box-shadow var(--transition), transform var(--transition);
    outline: none;
  }
  .search:focus, input[type="search"]:focus {
    box-shadow: 0 6px 30px rgba(99,240,255,0.06);
    transform: translateY(-2px);
  }

  /* Cards / Panels */
  .card, .panel, .widget {
    background: linear-gradient(180deg, rgba(255,255,255,0.02), rgba(255,255,255,0.01));
    border-radius: var(--radius);
    padding: 16px;
    border: 1px solid var(--glass-border);
    box-shadow: var(--shadow-1);
    backdrop-filter: blur(var(--glass-blur));
    margin-bottom: 16px;
  }
  .card h2, .panel h2 {
    margin: 0 0 8px 0;
    font-size: 1.05rem;
    color: var(--text);
  }
  .card p, .panel p { color: var(--muted); margin: 0; }

  /* Buttons */
  .btn, button, input[type="button"], input[type="submit"] {
    font-family: var(--ui-font);
    border: none;
    padding: 10px 14px;
    border-radius: 10px;
    cursor: pointer;
    transition: transform var(--transition), box-shadow var(--transition);
    background: linear-gradient(90deg, rgba(255,255,255,0.02), rgba(255,255,255,0.01));
    color: var(--text);
    border: 1px solid rgba(255,255,255,0.04);
  }
  .btn-primary {
    background: linear-gradient(90deg, rgba(99,240,255,0.12), rgba(110,242,142,0.06));
    color: #022227;
    box-shadow: 0 8px 30px rgba(99,240,255,0.06);
    border: 1px solid rgba(99,240,255,0.18);
    font-weight: 600;
  }
  .btn:hover, .btn-primary:hover {
    transform: translateY(-3px);
  }
  .btn-ghost {
    background: transparent;
    border: 1px dashed rgba(255,255,255,0.04);
    color: var(--muted);
  }

  /* Inputs / Form fields */
  input, textarea, select {
    background: rgba(0,0,0,0.18);
    border-radius: 10px;
    border: 1px solid rgba(255,255,255,0.04);
    padding: 10px 12px;
    color: var(--text);
    transition: border-color var(--transition), box-shadow var(--transition);
  }
  input:focus, textarea:focus, select:focus {
    border-color: rgba(99,240,255,0.4);
    box-shadow: 0 6px 22px rgba(99,240,255,0.06);
    outline: none;
  }

  /* Tables */
  table {
    width: 100%;
    border-collapse: collapse;
    background: transparent;
    color: var(--text);
    font-size: 0.95rem;
  }
  table thead th {
    text-align: left;
    padding: 10px 12px;
    color: var(--muted);
    font-weight: 600;
    font-size: 0.82rem;
    letter-spacing: 0.6px;
    text-transform: uppercase;
  }
  table tbody td {
    padding: 12px;
    border-top: 1px solid rgba(255,255,255,0.02);
  }
  table tbody tr:hover td {
    background: linear-gradient(90deg, rgba(255,255,255,0.01), transparent);
  }

  /* Cards listing (grid) */
  .grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
    gap: 14px;
  }

  /* Footer */
  footer {
    margin-top: 22px;
    padding: 12px;
    color: var(--muted);
    text-align: center;
    font-size: 0.9rem;
  }

  /* Notifications / badges */
  .badge {
    display: inline-block;
    padding: 6px 8px;
    font-size: 0.78rem;
    border-radius: 999px;
    background: linear-gradient(90deg, rgba(99,240,255,0.12), rgba(110,242,142,0.06));
    color: #022227;
    font-weight: 700;
  }

  /* Avatars */
  .avatar {
    width: 40px;
    height: 40px;
    border-radius: 10px;
    overflow: hidden;
    border: 1px solid rgba(255,255,255,0.04);
    background: linear-gradient(135deg, rgba(255,255,255,0.02), rgba(255,255,255,0.01));
    display: inline-flex;
    align-items: center;
    justify-content: center;
  }

  /* Code blocks */
  pre, code, .code {
    font-family: var(--mono);
    background: rgba(0,0,0,0.25);
    border-radius: 8px;
    padding: 10px;
    color: #cbeff6;
    overflow: auto;
  }

  /* Modal / dialogs */
  .modal, dialog[open] {
    background: linear-gradient(180deg, rgba(3,10,14,0.95), rgba(2,6,10,0.95));
    border-radius: 14px;
    border: 1px solid rgba(255,255,255,0.04);
    box-shadow: 0 30px 60px rgba(0,0,0,0.7);
    padding: 18px;
  }

  /* Tiny helpers */
  .muted { color: var(--muted); }
  .accent { color: var(--accent); }
  .accent-bg { background: linear-gradient(90deg, rgba(99,240,255,0.12), rgba(110,242,142,0.06)); color: #022227; padding: 6px 8px; border-radius: 8px; }

  /* Responsive tweaks */
  @media (max-width: 720px) {
    header, .topbar { flex-direction: column; align-items: stretch; gap: 8px; padding: 12px; }
    .container { margin: 12px; padding: 12px; }
    .search { max-width: 100%; }
  }

  /* Optional: highlight links with neon underline */
  a, a:link, a:visited {
    color: var(--accent);
    text-decoration: none;
    box-shadow: inset 0 -2px 0 rgba(99,240,255,0.08);
    transition: box-shadow var(--transition), transform var(--transition);
  }
  a:hover { box-shadow: inset 0 -30px 40px rgba(99,240,255,0.04); transform: translateY(-2px); }

  /* Accessibility: keep contrast for important text */
  strong, b { color: var(--text); font-weight: 700; }

  /* Fallback if specific selectors on the site are very different:
     Try to make core elements look consistent */
  header, .navbar, .topbar, .site-header, .site-nav { border-radius: 12px; }
  .card, .panel, .widget, article, section { transition: transform var(--transition), box-shadow var(--transition); }
  .card:hover, .panel:hover { transform: translateY(-6px); box-shadow: 0 18px 40px rgba(2,6,24,0.65); }
}
